// ─── File: src/main/java/com/bank/layered/model/InterestBearingAccount.java ───
// LAYER 2: abstract class EXTENDS Account AND IMPLEMENTS Auditable + Taxable
package com.bank.layered.model;

import com.bank.layered.capability.*;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

public abstract class InterestBearingAccount extends Account implements Auditable, Taxable {
    // ═══ EXTENDS Account: inherits accountId, balance, deposit() ═══
    // ═══ IMPLEMENTS Auditable + Taxable: can leave methods abstract ═══

    protected final BigDecimal annualRate;

    protected InterestBearingAccount(String accountId, BigDecimal balance, BigDecimal annualRate) {
        super(accountId, balance);  // calls Account's constructor
        this.annualRate = annualRate;
    }

    // NEW concrete method — interest calculation shared by all interest-bearing accounts
    public BigDecimal calculateMonthlyInterest() {
        return balance.multiply(annualRate).divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP);
    }

    // PARTIALLY implements Auditable — provides a base report
    @Override
    public List<String> generateAuditReport() {
        return List.of(
            "AccountId: " + accountId,
            "Type: " + getAccountType(),  // calls abstract method — resolved by concrete child!
            "Balance: Rs." + balance,
            "Annual Rate: " + annualRate.multiply(BigDecimal.valueOf(100)) + "%"
        );
    }

    // DOES NOT implement Taxable.calculateTax() → remains abstract
    // Concrete subclass MUST implement calculateTax()

    // getAccountType() from Account → still abstract, passed to concrete subclass

    public BigDecimal getAnnualRate() { return annualRate; }
}
// This class has 2 unimplemented methods: getAccountType() + calculateTax()
// Therefore it MUST be abstract!
