// ─── File: src/main/java/com/bank/layered/model/FixedDepositAccount.java ───
// LAYER 3: another concrete class — different implementation
package com.bank.layered.model;

import java.math.BigDecimal;

public class FixedDepositAccount extends InterestBearingAccount {

    private final int tenureMonths;

    public FixedDepositAccount(String accountId, BigDecimal balance, BigDecimal annualRate, int tenureMonths) {
        super(accountId, balance, annualRate);
        this.tenureMonths = tenureMonths;
    }

    @Override
    public String getAccountType() { return "FIXED_DEPOSIT"; }

    @Override
    public BigDecimal calculateTax() {
        // FD: tax only if interest > Rs.40,000 (threshold)
        BigDecimal yearlyInterest = calculateMonthlyInterest().multiply(BigDecimal.valueOf(12));
        if (yearlyInterest.compareTo(new BigDecimal("40000")) <= 0) return BigDecimal.ZERO;
        return yearlyInterest.multiply(new BigDecimal("0.10"));  // 10% TDS above threshold
    }

    @Override
    public String getTaxCategory() { return "FD_SPECIAL"; }  // overrides Taxable default method
}
```

```java
// ─── File: src/test/java/com/bank/layered/LayeredHierarchyTest.java ───
package com.bank.layered;

import com.bank.layered.capability.*;
import com.bank.layered.model.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class LayeredHierarchyTest {

    @Test
    void abstractClassCanExtendAndImplement() {
        // InterestBearingAccount extends Account AND implements Auditable + Taxable
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        assertThat(sa).isInstanceOf(Account.class);                 // extends Account (Recommended) 
        assertThat(sa).isInstanceOf(InterestBearingAccount.class);  // extends middle layer (Recommended) 
        assertThat(sa).isInstanceOf(Auditable.class);               // implements via middle (Recommended) 
        assertThat(sa).isInstanceOf(Taxable.class);                 // implements via middle (Recommended) 
    }

    @Test
    void layer2ProvidesPartialImplementation() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        // generateAuditReport() implemented by InterestBearingAccount (Layer 2)
        List<String> report = sa.generateAuditReport();
        assertThat(report).anyMatch(r -> r.contains("SAVINGS"));  // calls getAccountType() on Layer 3!
        assertThat(report).anyMatch(r -> r.contains("120000"));
    }

    @Test
    void layer3ProvidesRemainingImplementation() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        assertThat(sa.getAccountType()).isEqualTo("SAVINGS");
        assertThat(sa.calculateTax()).isGreaterThan(BigDecimal.ZERO);
    }

    @Test
    void differentConcreteClassesDifferentBehavior() {
        SavingsAccount sa = new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04"));
        FixedDepositAccount fd = new FixedDepositAccount("FD001", new BigDecimal("500000"), new BigDecimal("0.07"), 12);

        // Same interface (Taxable), different tax rules:
        BigDecimal savingsTax = sa.calculateTax();
        BigDecimal fdTax = fd.calculateTax();
        assertThat(savingsTax).isNotEqualTo(fdTax);  // different rules!

        // Different tax categories:
        assertThat(sa.getTaxCategory()).isEqualTo("STANDARD");   // default from Taxable interface
        assertThat(fd.getTaxCategory()).isEqualTo("FD_SPECIAL");  // overridden
    }

    @Test
    void chainOfInheritance() {
        FixedDepositAccount fd = new FixedDepositAccount("FD001", new BigDecimal("500000"), new BigDecimal("0.07"), 12);

        // From Account (Layer 1):
        fd.deposit(new BigDecimal("10000"));  // inherited concrete method
        assertThat(fd.getBalance()).isEqualByComparingTo("510000");

        // From InterestBearingAccount (Layer 2):
        BigDecimal interest = fd.calculateMonthlyInterest();
        assertThat(interest).isGreaterThan(BigDecimal.ZERO);  // inherited concrete method

        // From FixedDepositAccount (Layer 3):
        assertThat(fd.getAccountType()).isEqualTo("FIXED_DEPOSIT");  // implemented here
    }

    @Test
    void polymorphicProcessingAcrossLayers() {
        List<Account> accounts = List.of(
            new SavingsAccount("SAV001", new BigDecimal("120000"), new BigDecimal("0.04")),
            new FixedDepositAccount("FD001", new BigDecimal("500000"), new BigDecimal("0.07"), 12));

        // All are Accounts — polymorphic loop:
        accounts.forEach(a -> {
            assertThat(a.getAccountType()).isNotBlank();
            assertThat(a.getBalance()).isGreaterThan(BigDecimal.ZERO);
        });

        // All are Taxable — interface-based loop:
        accounts.stream()
            .filter(a -> a instanceof Taxable)
            .map(a -> (Taxable) a)
            .forEach(t -> assertThat(t.calculateTax()).isNotNull());
    }
}
